import React, { useState } from 'react';
import products from './CrudProducts.json';

const initialFormState = { id: '', name: '', description: '', quantity: '', price: '', mfgDate: '' };

const CrudProduct = () => {
  const [productList, setProductList] = useState(products);
  const [form, setForm] = useState(initialFormState);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleProduct = (action, id) => {
    if (action === 'add') {
      if (form.id && form.name) {
        setProductList([...productList, form]);
      }
    } else if (action === 'update') {
      setProductList(productList.map(product => product.id === id ? form : product));
    } else if (action === 'delete') {
      setProductList(productList.filter(product => product.id !== id));
    }
    setForm(initialFormState);
  };

  return (
    <div className="p-4">
      <h1 className="text-2xl font-bold mb-4">Product Management</h1>
      <form className="mb-4 flex gap-2">
        <input type="text" name="id" value={form.id} onChange={handleChange} placeholder="ID" className="border p-2" />
        <input type="text" name="name" value={form.name} onChange={handleChange} placeholder="Name" className="border p-2" />
        <input type="text" name="description" value={form.description} onChange={handleChange} placeholder="Description" className="border p-2" />
        <input type="text" name="quantity" value={form.quantity} onChange={handleChange} placeholder="Quantity" className="border p-2" />
        <input type="text" name="price" value={form.price} onChange={handleChange} placeholder="Price" className="border p-2" />
        <input type="date" name="mfgDate" value={form.mfgDate} onChange={handleChange} className="border p-2" />
        <button type="button" onClick={() => handleProduct('add')} className="bg-blue-500 text-white p-2 rounded">Add</button>
        <button type="button" onClick={() => handleProduct('update', form.id)} className="bg-green-500 text-white p-2 rounded">Update</button>
      </form>

      <table className="w-full border-collapse border">
        <thead>
          <tr>
            <th className="border p-2">ID</th>
            <th className="border p-2">Name</th>
            <th className="border p-2">Description</th>
            <th className="border p-2">Quantity</th>
            <th className="border p-2">Price</th>
            <th className="border p-2">Mfg Date</th>
            <th className="border p-2">Actions</th>
          </tr>
        </thead>
        <tbody>
          {productList.map(product => (
            <tr key={product.id}>
              <td className="border p-2">{product.id}</td>
              <td className="border p-2">{product.name}</td>
              <td className="border p-2">{product.description}</td>
              <td className="border p-2">{product.quantity}</td>
              <td className="border p-2">{product.price}</td>
              <td className="border p-2">{product.mfgDate}</td>
              <td className="border p-2">
                <button onClick={() => setForm(product)} className="bg-yellow-400 text-white p-1 rounded mr-2">Edit</button>
                <button onClick={() => handleProduct('delete', product.id)} className="bg-red-500 text-white p-1 rounded">Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default CrudProduct;
